function burst(auto=false){if(isExpandedHighland()&&highland?.fall){boostInWaterfall();return;}if(leap.active)return;if(state!=='playing'||(boostUnlimited<=0&&energy<.4)||dashCooldown>0)return;if(boostUnlimited<=0)energy-=.4;dashTime=.38;dashCooldown=boostUnlimited>0?.18:.55;boostFlash=.18;let dx=(keys.has('ArrowRight')||keys.has('d')?1:0)-(keys.has('ArrowLeft')||keys.has('a')?1:0),dy=(keys.has('ArrowDown')||keys.has('s')?1:0)-(keys.has('ArrowUp')||keys.has('w')?1:0);if(!dx&&!dy)dx=nessie.face;const len=Math.hypot(dx,dy);nessie.vx=dx/len*850;nessie.vy=dy/len*850;tone(180,.18,.035);}
