function retryStory(){const palaceExit=isPalace()&&checkpoint>=3900&&!!queen?.victoryReady,ranaExit=stage===3&&checkpoint>=3900&&((isNessieFinal()&&!!nessieTwist?.ready)||(!isNessieFinal()&&!!rana?.victoryReady));if(isNessieFinal()&&!ranaExit){nessieTwist=null;beginNessieFinal();nessieNext("charge");boss.active=true;}if(isExpandedHighland())resetHighlandRetry();if(isPalace()&&!palaceExit)resetPalaceRetry();if(isTraining())resetTrainingRetry();if(isRana()&&boss&&!ranaExit){boss.hp=boss.max;boss.active=false;bossAnnounced=false;dialogueSeen.delete('final-boss-win');resetRana();}if(palaceExit){queen.victoryReady=true;if(boss){boss.hp=0;boss.active=false;}setupPalaceExitCorridor();}if(ranaExit){if(isNessieFinal()){nessieTwist.ready=true;nessieTwist.phase='defeated';}else rana.victoryReady=true;if(boss){boss.hp=0;boss.active=false;}setupRanaExitCorridor();}heartJumpTime=0;bossLeapReady=false;bossLessonTime=0;resetLeap();boostUnlimited=0;dashTime=0;dashCooldown=0;motionTrail=[];for(const p of powerups)p.taken=false;health=5;invincible=2;nessie.x=checkpoint;nessie.y=500;nessie.vx=0;nessie.vy=0;energy=1;projectiles=[];if(boss&&boss.hp>0){boss.hp=boss.max;boss.clock=0;boss.vulnerable=false;boss.hitCooldown=0;boss.shot=.8;boss.laserActive=false;boss.shockActive=false;}state='playing';keys.clear();$('overlay').style.display='none';canvas.focus();hud();flash('Back at the checkpoint. You’ve got this!');}
function finishStory(won){if(won&&mode==='sarah'&&!dialogueSeen.has('final')){openDialogue('final',()=>finishStory(true));return;}state='finished';clearHeldControls();$('boss-hud').style.display='none';$('overlay').style.display='flex';const rating=won?3:maxCombo>=3?2:1,badge=won?'Stage Clear!':'Adventure Paused',bonuses=resultBonusRow(['<b>'+goldCount+'</b> pearls','<b>'+chestCount+'</b> chests','<b>×'+maxCombo+'</b> best combo']);
 $('overlay').innerHTML=`<div class="start-card v62-results"><span class="v62-result-badge">${badge}</span><h1 class="result-title">${won?(mode==='sarah'?'Sarah saves the lagoon!':'A legendary journey!'):'Try again, little legend.'}</h1><div class="v62-result-score"><small>ADVENTURE SCORE</small><strong>${score.toLocaleString()}</strong></div>${resultStars(rating)}${bonuses}<p>${won?'The lagoon is safe and the crowns are back where they belong.<br>Time to dance!':'Dodge the projectiles. Wait for the glow.<br>Then boost straight into the boss!'}</p><button class="play" id="story-again">${won?'Play story again':'Continue from checkpoint'} <span>▶</span></button><button class="restart" id="story-menu">Choose a mode</button></div>`;
 $('story-again').onclick=won?start:retryStory;$('story-menu').onclick=showMenu;if(won)tone(1046,.5);hud();}
function starShape(x,y,r,color){ctx.save();ctx.translate(x,y);ctx.rotate(reducedMotion?0:elapsed*4);ctx.beginPath();for(let i=0;i<10;i++){let a=i/10*Math.PI*2-Math.PI/2,rad=i%2?r*.43:r;const px=Math.cos(a)*rad,py=Math.sin(a)*rad;i?ctx.lineTo(px,py):ctx.moveTo(px,py);}ctx.closePath();ctx.fillStyle=color;ctx.fill();ctx.strokeStyle='#ffdfa6';ctx.lineWidth=2;ctx.stroke();ctx.restore();}
function drawActor(art,x,y,width,mirror=false){const kind=art===carloArt?'carlo':'miguel',phase=(boss?.clock||0)%(kind==='carlo'?7.4:6.8),pose=(boss?.hitCooldown||0)>.6?'stagger':boss?.vulnerable?'vulnerable':phase<.9?'charge':phase<(kind==='carlo'?3.6:2.8)?'volley':kind==='miguel'&&phase<3.8?'rush':'idle';if(drawBossV4(kind,x-camera,y,width,performance.now()/1000,pose,mirror))return;releaseBossActor(art,x,y,width,mirror);}
function drawProjectile(p,t){if(drawSparkProjectile(p,t))return;if(drawBossProjectileV4(p,t))return;if(drawFamilyProjectile(p,t))return;const x=p.x-camera;if(x<-70||x>vw+70)return;const y=p.y;ctx.save();ctx.strokeStyle=p.type==='acid'?'#c3ff7c55':p.type==='spore'?'#ffadf555':'#b5faff44';ctx.lineWidth=p.type==='pearl'?5:3;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x-p.vx*.07,y-p.vy*.07);ctx.stroke();ctx.restore();const spin=reducedMotion?0:(p.age||0)*4+(p.phase||0);ctx.save();ctx.translate(x,y);if(p.variant==='homing'){ctx.strokeStyle='#fff1a4aa';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,28+Math.sin(t*8)*3,0,Math.PI*2);ctx.stroke();}if(p.type==='star'){ctx.rotate(spin);starShape(0,0,21,p.variant==='boomerang'?'#ff7cc6':'#fb796f');}else if(p.type==='shell'){ctx.rotate(spin);ctx.fillStyle='#ffe4bd';ctx.strokeStyle='#d78d72';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,19,Math.PI,Math.PI*2);ctx.lineTo(0,14);ctx.closePath();ctx.fill();ctx.stroke();for(let a=0;a<5;a++){ctx.beginPath();ctx.moveTo(0,12);ctx.lineTo(-15+a*7,-10);ctx.stroke();}}else if(p.type==='pearl'){ctx.shadowColor='#9ef7ff';ctx.shadowBlur=18;ctx.fillStyle='#d7fbff';ctx.strokeStyle='#82dbe4';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,15,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.shadowBlur=0;ctx.strokeStyle='#f4ffff99';ctx.beginPath();ctx.arc(0,0,25+Math.sin(t*5)*3,0,Math.PI*2);ctx.stroke();}else if(p.type==='jelly'){ctx.fillStyle='#c29cff';ctx.strokeStyle='#f0d4ff';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,20,Math.PI,Math.PI*2);ctx.lineTo(20,7);ctx.quadraticCurveTo(10,14,0,7);ctx.quadraticCurveTo(-10,14,-20,7);ctx.closePath();ctx.fill();ctx.stroke();ctx.strokeStyle='#ebc7ff';for(let i=-2;i<=2;i++){ctx.beginPath();ctx.moveTo(i*7,7);ctx.quadraticCurveTo(i*8+Math.sin(t*7+i)*5,20,i*7-2,31);ctx.stroke();}}else if(p.type==='mine'){ctx.rotate(spin*.6);ctx.shadowColor='#ffbd74';ctx.shadowBlur=15;ctx.fillStyle='#ff9e58';ctx.strokeStyle='#ffe1a1';ctx.lineWidth=2;ctx.beginPath();for(let i=0;i<16;i++){const a=i/16*Math.PI*2,r=i%2?13:25;const px=Math.cos(a)*r,py=Math.sin(a)*r;i?ctx.lineTo(px,py):ctx.moveTo(px,py);}ctx.closePath();ctx.fill();ctx.stroke();ctx.shadowBlur=0;ctx.fillStyle='#6d3150';ctx.beginPath();ctx.arc(0,0,8,0,Math.PI*2);ctx.fill();}else if(p.type==='acid'){ctx.shadowColor='#9dff72';ctx.shadowBlur=17;ctx.fillStyle='#a8ef64';ctx.strokeStyle='#e7ff9f';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,16+Math.sin(t*8+(p.phase||0))*2,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.shadowBlur=0;ctx.fillStyle='#79c94b';ctx.beginPath();ctx.arc(-5,-5,4,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.moveTo(-10,13);ctx.quadraticCurveTo(-12,26,-6,31);ctx.moveTo(2,14);ctx.quadraticCurveTo(0,24,6,28);ctx.strokeStyle='#bcff73';ctx.stroke();}else if(p.type==='spore'){ctx.shadowColor='#ff9ae9';ctx.shadowBlur=15;ctx.fillStyle='#d76ac8';ctx.strokeStyle='#ffd0f3';ctx.lineWidth=2;ctx.beginPath();ctx.arc(-10,2,10,0,Math.PI*2);ctx.arc(3,-8,12,0,Math.PI*2);ctx.arc(12,5,9,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.shadowBlur=0;ctx.fillStyle='#ffe8ff';ctx.beginPath();ctx.arc(-6,-1,2,0,Math.PI*2);ctx.arc(8,-6,2,0,Math.PI*2);ctx.fill();}else if(p.type==='seed'){ctx.rotate(spin*.7);ctx.shadowColor='#b7ff72';ctx.shadowBlur=14;ctx.fillStyle='#75d45c';ctx.strokeStyle='#e0ff9d';ctx.lineWidth=2;ctx.beginPath();for(let i=0;i<12;i++){const a=i/12*Math.PI*2,r=i%2?11:23;const px=Math.cos(a)*r,py=Math.sin(a)*r;i?ctx.lineTo(px,py):ctx.moveTo(px,py);}ctx.closePath();ctx.fill();ctx.stroke();ctx.shadowBlur=0;ctx.fillStyle='#365f4c';ctx.beginPath();ctx.arc(0,0,6,0,Math.PI*2);ctx.fill();}ctx.restore();}
function drawStory(t){for(let i=0;i<obstacles.length;i++){const o=obstacles[i],x=o.x-camera;if(x>vw+80||x+o.w<-80)continue;drawBarrier(o,x,t,i);}
for(const e of enemies){if(e.hp<=0||isPalace())continue;releaseCreature(e,t);}
if(isRana()){drawRanaArena(t);drawRanaHazards(t);drawRanaAttacks(t);}if(bossDefeat>0&&stage>=0&&stage<2)drawBossDefeat(t);if(isPalace())drawPalaceWorld(t);if(isTraining())drawTrainingWorld(t);
for(const p of projectiles){if(isRana())drawRanaProjectileTrail(p,t);drawProjectile(p,t);}
if(boss&&boss.hp>0){const bx=boss.x-camera,by=boss.y;if(stage>=0&&stage<2&&boss.vulnerable){ctx.strokeStyle='#a1ffd5';ctx.shadowBlur=18;ctx.shadowColor='#9affc5';ctx.lineWidth=5;ctx.beginPath();ctx.ellipse(bx,by,164,117,0,0,Math.PI*2);ctx.stroke();ctx.shadowBlur=0;ctx.fillStyle='#b3ffdc';ctx.font='1000 23px Nunito,sans-serif';ctx.textAlign='center';drawCueBadge(bx,by-(isRana()?203:135),'boost',true,t);}else if(stage>=0&&stage<2&&boss.active&&boss.clock%(stage===0?7.4:stage===1?6.8:10)<.9){ctx.fillStyle='#ffd482';ctx.font='1000 40px sans-serif';ctx.textAlign='center';drawCueBadge(bx,by-(isRana()?203:135),'warning',false,t);}if(isNessieFinal()){}else if(isRana())drawRanaBoss(t);else if(isPalace())drawQueen(t);else if(isTraining())drawKingBoss(t);else drawActor(stage===0?carloArt:miguelArt,boss.x,boss.y,stage===0?290:320);}
if(isRana()&&boss?.hp<=0)drawRanaBoss(t);if(isPalace()&&boss?.hp<=0)drawQueen(t);if(isTraining()&&boss?.hp<=0)drawKingBoss(t);drawNessieSubplot(t);drawOrnatePortal(W-170-camera,540,260,t,familyPortalOpen());}

