function selectDialogue(index){const options=$('dialogue-options')?.querySelectorAll('button')||[];if(!options.length)return;dialogueChoiceIndex=clamp(index,0,options.length-1);options[dialogueChoiceIndex].click();}
function openDialogue(id,after=null){return startConversation(id,after);}
function finishDialogue(){dialogueFlow=null;document.querySelector('.game-shell')?.classList.remove('conversation-active');$('dialogue-panel').style.display='none';keys.clear();state='playing';dashTime=0;nessie.vx*=.25;nessie.vy*=.25;invincible=Math.max(invincible,.65);const after=dialogueAfter;dialogueAfter=null;if(after)after();else canvas.focus();}
const menuMarkup=$('overlay').innerHTML;
let frameDelta=1/60;function frame(now){const dt=Math.min((now-last)/1000||0,.1);frameDelta=dt;last=now;if(state==='ready')titleSceneTime+=Math.min(dt,.05);advanceSimulation(dt);if(now-lastHudPaint>=50){hud();lastHudPaint=now;}updateMusic(dt);syncSplashControls();draw(now/1000);syncTutorialUi();syncHighlandUi();if(now>toastUntil)$('toast').style.opacity='0';requestAnimationFrame(frame);}requestAnimationFrame(frame);
$('play').onclick=start;$('modes').onclick=showMenu;$('mode-story').onclick=()=>chooseMode('story');$('mode-trial').onclick=()=>chooseMode('trial');$('mode-sarah').onclick=()=>chooseMode('sarah');bindMenu();$('pause').onclick=pause;$('sound').onclick=toggleGameSound;initGameSound();$('full').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.querySelector('.game-shell').requestFullscreen();}catch{flash('Fullscreen is unavailable in this browser');}};
function controlToken(key){const raw=String(key||''),lower=raw.toLowerCase();if(lower==='shift')return'j';const k=key===' '?'space':lower;return k.startsWith('arrow')?k:k;}
function syncControlVisual(key,down){const token=controlToken(key);for(const el of document.querySelectorAll('[data-control-key]'))if(el.dataset.controlKey===token)el.classList.toggle('control-active',!!down);}
function clearControlVisuals(){for(const el of document.querySelectorAll('[data-control-key]'))el.classList.remove('control-active');}
window.addEventListener('keydown',e=>{if(handleConversationKey(e))return;const key=e.key.length===1?e.key.toLowerCase():e.key,jumpKey=key==='j'||key==='Shift'||e.code==='KeyJ'||e.code==='ShiftLeft'||e.code==='ShiftRight';if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' ','w','a','s','d','p','j'].includes(String(e.key).toLowerCase())||e.key.startsWith('Arrow')||jumpKey){if(e.target.tagName!=='BUTTON')e.preventDefault();}syncControlVisual(jumpKey?'j':key,true);if(jumpKey&&!e.repeat){requestJump();return;}if(key==='p'&&!e.repeat){pause();return;}keyboardHeld.add(key);keys.add(key);if(key===' '&&!e.repeat)burst();});window.addEventListener('keyup',e=>{const key=e.key.length===1?e.key.toLowerCase():e.key,jumpKey=key==='j'||key==='Shift'||e.code==='KeyJ'||e.code==='ShiftLeft'||e.code==='ShiftRight';keyboardHeld.delete(key);if(!touchOwnedKeys.has(key)){keys.delete(key);syncControlVisual(jumpKey?'j':key,false);}});
function clearHeldControls(){keys.clear();clearControlVisuals();for(const [pointerId,b] of activeTouchPointers){try{if(b.hasPointerCapture?.(pointerId))b.releasePointerCapture?.(pointerId);}catch{}b.classList?.remove('is-pressed');b.setAttribute?.('aria-pressed','false');}activeTouchPointers.clear();resetTouchDirections();keys.clear();}
window.addEventListener('blur',()=>{clearHeldControls();if(state==='playing'||state==='portal')pause();});document.addEventListener('visibilitychange',()=>{if(document.hidden){clearHeldControls();if(state==='playing'||state==='portal')pause();}});
