function setupPowerups(){const placements=isRana()?[[720,540,'heart'],[1870,690,'heart'],[2660,490,'boost'],[2970,650,'heart'],[3060,745,'boost'],[3480,520,'boost']]:[[670,570,'heart'],[1550,680,'heart'],[1980,460,'boost'],[2640,730,'heart'],[2940,520,'boost']],sx=isExtendedStoryStage()?storyStretchX:x=>x;powerups=placements.map(([x,y,type],i)=>({x:sx(x),y,type,phase:i*1.7,taken:false}));}
function collectPowerup(p){familyPickup(p);p.taken=true;const heart=p.type==='heart',healed=heart&&health<5;if(heart){health=Math.min(5,health+1);heartJumpTime=12;}else{boostUnlimited=Math.min(16,boostUnlimited+8);energy=1;dashCooldown=0;}rewardPopup(p.x,p.y-30,heart?(healed?'HEART +1':'HEART FULL'):'PEARL +8s',heart?'heart':'pearl',heart?'#ffb5d0':'#a9fff4',1.45);if(heart&&healed)showRewardBanner('heart','Heart +1','SARAH IS READY TO SWIM');else if(!heart)showRewardBanner('time','Pearl Bonus!','8s MERMAID BURST');for(let i=0;i<30;i++){const a=i/30*Math.PI*2;particles.push({x:p.x,y:p.y,vx:Math.cos(a)*140,vy:Math.sin(a)*140,life:.9,max:1,color:heart?'#ff9cc8':'#9affec',r:3+i%3,bubble:i%3===0});}tone(heart?880:1200,.2);}
function drawGlossyHeart(x,y,size,t){
 ctx.save();ctx.translate(x,y);ctx.scale(size/44,size/44);ctx.shadowColor='#ff62bd';ctx.shadowBlur=16;const g=ctx.createLinearGradient(-18,-22,18,24);g.addColorStop(0,'#ffd6ee');g.addColorStop(.3,'#ff88cb');g.addColorStop(1,'#e72a88');ctx.fillStyle=g;ctx.strokeStyle='#fff0f7';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(0,27);ctx.bezierCurveTo(-5,20,-31,5,-31,-10);ctx.bezierCurveTo(-31,-27,-9,-31,0,-16);ctx.bezierCurveTo(9,-31,31,-27,31,-10);ctx.bezierCurveTo(31,5,5,20,0,27);ctx.closePath();ctx.fill();ctx.stroke();ctx.shadowBlur=0;ctx.globalAlpha=.8;ctx.fillStyle='#fff';ctx.beginPath();ctx.ellipse(-12,-13,7,4,-.5,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;ctx.fillStyle='#fff0ff';ctx.font='14px sans-serif';ctx.fillText('✦',20,-20);ctx.restore();}
