  ctx.save();ctx.translate(x,y);ctx.fillStyle='#0b3346e8';ctx.strokeStyle='#d3f9ed88';ctx.lineWidth=1.5;ctx.beginPath();ctx.roundRect(-38,-13,76,26,7);ctx.fill();ctx.stroke();ctx.fillStyle='#edfff9';ctx.textAlign='center';ctx.font='800 10px Nunito,sans-serif';ctx.fillText('J / SHIFT',0,4);ctx.restore();
