function jumpPose(){
  if(!leap.breached||reducedMotion)return {angle:0,squash:1,stretch:1,skew:0};
  const p=clamp((leap.airTime||0)/(leap.airDuration||1.05),0,1),arc=Math.sin(p*Math.PI),u=clamp((p-.07)/.83,0,1),ease=u*u*(3-2*u),v=leap.variant;
  const turns=v==='boss'?2:v==='combo'||v==='boost'?1:0;
  const roll=v==='boss'?Math.sin(ease*Math.PI*4):v==='combo'?Math.sin(ease*Math.PI*4):v==='boost'?Math.sin(ease*Math.PI*2):Math.sin(p*Math.PI*2);
  // A perspective roll, delayed tail and compact midair tuck sell the twist.
  return {angle:turns*Math.PI*2*ease+(v==='standard'?-.48*Math.sin(p*Math.PI*2):v==='heart'?-.7*Math.sin(p*Math.PI*2):.14*arc*roll),squash:1-Math.abs(roll)*arc*(turns?.36:.16),stretch:1+arc*(v==='boss'?.14:.08)-Math.abs(roll)*arc*.12,skew:roll*arc*(v==='combo'?.23:.15)};
}
function jumpParticles(dt){
  leap.traceClock=(leap.traceClock||0)+dt;if(leap.traceClock>=.025){leap.traceClock=0;leap.trace??=[];leap.trace.push({x:nessie.x,y:nessie.y});if(leap.trace.length>24)leap.trace.shift();}
  leap.particleClock=(leap.particleClock||0)+dt;if(leap.particleClock<.035)return;leap.particleClock=0;
  const variant=leap.variant;if(!variant||reducedMotion)return;
  const t=leap.airTime||0,angle=t*9,r=variant==='boss'?44:28;
  const color=variant==='boss'?['#ffbadf','#e3baff','#b1f6ff','#ffedab'][Math.floor(t*24)%4]:variant==='combo'||variant==='heart'?'#ffafda':'#c5fff1';
  const x=nessie.x+Math.cos(angle)*r,y=nessie.y+Math.sin(angle)*r;
  particles.push({x,y,vx:-nessie.vx*.12,vy:25,life:.65,max:.65,r:variant==='boss'?5:3,color});
  if((variant==='combo'||variant==='heart')&&!reducedMotion&&Math.floor(t*24)%4===0)particles.push({x,y,vx:-nessie.vx*.1,vy:-20,life:.7,max:.7,r:4,color,heart:true});
}

function drawJumpRibbon(){
  if(!leap.active||!leap.breached||reducedMotion||!leap.trace?.length)return;
  const colors=leap.variant==='boss'?['#ffb7df','#debaff','#a7edff']:leap.variant==='combo'?['#ff9dcd','#ffe7ad']:leap.variant==='heart'?['#ffb2d2']:['#bbfff0'];
  ctx.save();ctx.lineCap='round';ctx.lineJoin='round';
  for(let band=0;band<colors.length;band++)for(let i=1;i<leap.trace.length;i++){
    const a=leap.trace[i-1],b=leap.trace[i],fade=i/leap.trace.length;
    ctx.strokeStyle=colors[band];ctx.shadowColor=colors[band];ctx.shadowBlur=8;ctx.globalAlpha=fade*.5;ctx.lineWidth=2+fade*3;
    const off=(band-(colors.length-1)/2)*8,wave=Math.sin(i*.5-leap.airTime*12+band*Math.PI)*fade*(leap.variant==='boss'?20:leap.variant==='combo'?16:7);
    ctx.beginPath();ctx.moveTo(a.x-camera,a.y+off+wave);ctx.lineTo(b.x-camera,b.y+off+wave);ctx.stroke();
  }ctx.restore();
}
