function drawJumpTwist(front){
 if(!leap.active||!leap.breached||reducedMotion||state==='portal')return;
 const p=clamp(leap.airTime/(leap.airDuration||1.05),0,1),fade=Math.sin(p*Math.PI),variant=leap.variant;
 if(fade<.05)return;
 const bands=variant==='boss'?3:variant==='combo'?2:1,colors=variant==='boss'?['#fff1ad','#edb2ff','#a1fff1']:variant==='combo'?['#ffbadc','#fff0b4']:['#b6fff3'];
 ctx.save();ctx.translate(nessie.x-camera,nessie.y);ctx.rotate(-.18*nessie.face);ctx.lineCap='round';
 for(let band=0;band<bands;band++){const phase=leap.airTime*(variant==='boss'?13:10)+band*2.1;
 ctx.strokeStyle=colors[band];ctx.shadowColor=colors[band];ctx.shadowBlur=10;ctx.lineWidth=2.4;ctx.globalAlpha=fade*(front?.55:.25);ctx.beginPath();let drawing=false;
 for(let i=0;i<=40;i++){const u=i/40,a=u*Math.PI*2+phase,z=Math.sin(a),visible=front?z>=0:z<0,x=(u-.5)*210,y=Math.cos(a)*(18+band*7);
 if(visible){if(!drawing)ctx.moveTo(x,y);else ctx.lineTo(x,y);drawing=true;}else drawing=false;}
 ctx.stroke();if(front){const a=phase+band,px=Math.cos(a)*95,py=Math.sin(a)*31;ctx.fillStyle=colors[band];ctx.globalAlpha=fade*.8;ctx.beginPath();ctx.moveTo(px,py-5);ctx.lineTo(px+2,py-1);ctx.lineTo(px+6,py);ctx.lineTo(px+2,py+2);ctx.lineTo(px,py+6);ctx.lineTo(px-2,py+2);ctx.lineTo(px-6,py);ctx.lineTo(px-2,py-1);ctx.closePath();ctx.fill();}}
 ctx.restore();
}

